public class Main {
    static List<List<Integer>> subsetsWithDupBrute(int[] nums) {
        int n = nums.length;
        Set<String> seen = new HashSet<>();
        List<List<Integer>> result = new ArrayList<>();
        for (int mask = 0; mask < (1 << n); mask++) {
            List<Integer> subset = new ArrayList<>();
            for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) subset.add(nums[i]);
            List<Integer> sortedSubset = new ArrayList<>(subset);
            Collections.sort(sortedSubset);
            String key = sortedSubset.toString();
            if (seen.add(key)) result.add(subset);      // deduplicate after generating
        }
        return result;
    }
}

