#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> subsetsWithDupBrute(vector<int>& nums) {
    int n = nums.size();
    set<vector<int>> seen;
    vector<vector<int>> result;
    for (int mask = 0; mask < (1 << n); mask++) {
        vector<int> subset;
        for (int i = 0; i < n; i++) if (mask & (1 << i)) subset.push_back(nums[i]);
        vector<int> key = subset;
        sort(key.begin(), key.end());
        if (seen.find(key) == seen.end()) {           // deduplicate after generating
            seen.insert(key);
            result.push_back(subset);
        }
    }
    return result;
}

